"use client";

import styles from "./style.module.scss";
import gsap from "gsap";
import { useGSAP } from "@gsap/react";
import { useRef } from "react";
import { SplitText } from "gsap/SplitText";
import Image from "next/image";

gsap.registerPlugin(SplitText, useGSAP);

const COLLECTION_TAGS = [
    { text: "Classic Elegance", italic: true },
    { text: "CRYSTAL EMBELLISHED" },
    { text: "BOLD COLORS" },
    { text: "STATEMENT PLATFORMS" },
    { text: "METALLIC RADIANCE" },
    { text: "FLORAL FANTASY" },
    { text: "SCULPTED ARTISTRY" },
    { text: "LUXURY LEATHER" },
    { text: "FIERCE ANIMAL PRINTS" },
    { text: "EMBOSSED TEXTURES" },
    { text: "SUEDE SOPHISTICATION" },
    { text: "VELVET VIBES" },
];

export default function Collection() {
    const containerRef = useRef<HTMLElement>(null);
    const headingRef = useRef<HTMLHeadingElement>(null);
    const tagsRef = useRef<HTMLDivElement>(null);
    const footerRef = useRef<HTMLDivElement>(null);

    useGSAP(
        () => {
            if (headingRef.current) {
                const headingSplit = SplitText.create(headingRef.current, {
                    type: "chars",
                    mask: "chars",
                });

                gsap.from(headingSplit.chars, {
                    yPercent: 120,
                    duration: 1.1,
                    ease: "power4.out",
                    stagger: 0.03,
                });
            }

            if (tagsRef.current) {
                const items = tagsRef.current.querySelectorAll(`.${styles.tagItem}`);
                gsap.from(items, {
                    opacity: 0,
                    y: 15,
                    duration: 0.8,
                    ease: "power3.out",
                    stagger: 0.04,
                    delay: 0.2,
                });
            }

            if (footerRef.current) {
                gsap.from(footerRef.current, {
                    opacity: 0,
                    y: 20,
                    duration: 0.8,
                    ease: "power3.out",
                    delay: 0.5,
                });
            }
        },
        { scope: containerRef }
    );

    return (
        <section className={styles.collection} ref={containerRef}>
            <div className={styles.imageWrapper}>
                <Image
                    src="/images/collection.jpg"
                    alt="Collection Background"
                    fill
                    priority
                    unoptimized
                    className={styles.bgImage}
                />
                <div className={styles.overlay} />
            </div>

            <div className={styles.content}>
                <header className={styles.header}>
                    <h1 ref={headingRef}>COLLECTIONS</h1>
                </header>

                <div className={styles.centerContent}>
                    <div className={styles.tagsGrid} ref={tagsRef}>
                        {COLLECTION_TAGS.map((tag, index) => (
                            <span key={index} className={styles.tagItem}>
                <span className={tag.italic ? styles.italicText : styles.tagText}>
                  {tag.text}
                </span>
                                {index < COLLECTION_TAGS.length - 1 && (
                                    <span className={styles.slash}>/</span>
                                )}
              </span>
                        ))}
                    </div>

                    <div className={styles.seasonInfo}>
                        <span>FALL</span>
                        <span className={styles.slash}>/</span>
                        <div className={styles.stacked}>
                            <span>WINTER</span>
                            <span>2024</span>
                        </div>
                    </div>
                </div>

                <footer className={styles.footer} ref={footerRef}>
                    <div className={styles.partners}>
                        <h2>OUR PARTNERS</h2>
                        <p>
                            STRIDE PROUDLY COLLABORATES WITH ESTEEMED LUXURY PARTNERS,
                            CURATING EXCELLENCE TO ELEVATE EVERY STEP INTO AN UNPARALLELED
                            EXPERIENCE.
                        </p>
                    </div>

                    <div className={styles.brandLogos}>
                        <svg width="123" height="28" viewBox="0 0 123 28" fill="none" xmlns="http://www.w3.org/2000/svg" xmlnsXlink="http://www.w3.org/1999/xlink">
                            <mask id="mask0_1_100" style={{ maskType: "alpha" }} maskUnits="userSpaceOnUse" x="0" y="0" width="123" height="28">
                                <rect width="122.84" height="27.6436" fill="url(#pattern0_1_100)"/>
                            </mask>
                            <g mask="url(#mask0_1_100)">
                                <rect x="-4.94238" width="131.811" height="27.6436" fill="#FDEBDD"/>
                            </g>
                            <defs>
                                <pattern id="pattern0_1_100" patternContentUnits="objectBoundingBox" width="1" height="1">
                                    <use xlinkHref="#image0_1_100" transform="matrix(0.00149031 0 0 0.00662252 -0.0968703 -1.49669)"/>
                                </pattern>
                                <image id="image0_1_100" width="800" height="600" preserveAspectRatio="none" xlinkHref="data:image/png;base64,"/>
                            </defs>
                        </svg>


                        <svg width="25" height="51" viewBox="0 0 25 51" fill="none" xmlns="http://www.w3.org/2000/svg" xmlnsXlink="http://www.w3.org/1999/xlink">
                            <mask id="mask0_1_103" style={{ maskType: "alpha" }} maskUnits="userSpaceOnUse" x="0" y="0" width="25" height="51">
                                <rect width="24.9392" height="51" fill="url(#pattern0_1_103)"/>
                            </mask>
                            <g mask="url(#mask0_1_103)">
                                <rect width="24.9392" height="51" fill="#FDEBDD"/>
                            </g>
                            <defs>
                                <pattern id="pattern0_1_103" patternContentUnits="objectBoundingBox" width="1" height="1">
                                    <use xlinkHref="#image0_1_103" transform="matrix(0.0026455 0 0 0.00129366 -1.60053 -0.276843)"/>
                                </pattern>
                                <image id="image0_1_103" width="1600" height="1200" preserveAspectRatio="none" xlinkHref="data:image/png;base64,"/>
                            </defs>
                        </svg>


                        <svg width="94" height="54" viewBox="0 0 94 54" fill="none" xmlns="http://www.w3.org/2000/svg" xmlnsXlink="http://www.w3.org/1999/xlink">
                            <mask id="mask0_1_106" style={{ maskType: "alpha" }} maskUnits="userSpaceOnUse" x="0" y="0" width="94" height="54">
                                <rect width="93.417" height="53.6651" fill="url(#pattern0_1_106)"/>
                            </mask>
                            <g mask="url(#mask0_1_106)">
                                <rect width="93.417" height="51.4683" fill="#FDEBDD"/>
                            </g>
                            <defs>
                                <pattern id="pattern0_1_106" patternContentUnits="objectBoundingBox" width="1" height="1">
                                    <use xlinkHref="#image0_1_106" transform="matrix(0.00111982 0 0 0.00194932 -0.0727884 -0.495127)"/>
                                </pattern>
                                <image id="image0_1_106" width="1024" height="1024" preserveAspectRatio="none" xlinkHref="data:image/png;base64,"/>
                            </defs>
                        </svg>


                        <svg width="65" height="29" viewBox="0 0 65 29" fill="none" xmlns="http://www.w3.org/2000/svg" xmlnsXlink="http://www.w3.org/1999/xlink">
                            <mask id="mask0_1_109" style={{ maskType: "alpha" }} maskUnits="userSpaceOnUse" x="0" y="0" width="65" height="29">
                                <rect width="64.8254" height="28.8803" fill="url(#pattern0_1_109)"/>
                            </mask>
                            <g mask="url(#mask0_1_109)">
                                <rect y="1.54895" width="64.3596" height="34.6253" fill="#FDEBDD"/>
                            </g>
                            <defs>
                                <pattern id="pattern0_1_109" patternContentUnits="objectBoundingBox" width="1" height="1">
                                    <use xlinkHref="#image0_1_109" transform="matrix(0.000418764 0 0 0.000939968 -0.132934 -0.438172)"/>
                                </pattern>
                                <image id="image0_1_109" width="3000" height="2000" preserveAspectRatio="none" xlinkHref="data:image/png;base64,"/>
                            </defs>
                        </svg>

                    </div>
                </footer>
            </div>
        </section>
    );
}